def choose_lever(problem):
    if problem == "stale facts":
        return "RAG"
    if problem == "tone or format":
        return "Prompting"
    if problem == "stable repeated label error":
        return "Fine-tuning"

for p in ["stale facts", "tone or format", "stable repeated label error"]:
    print(p, "->", choose_lever(p))
